import { registerResource } from '@projexlight/sdk-resource-registry';

const row = await registerResource({
  resource_id: 'aws:s3:projex-evidence-prod',
  resource_type: 's3_bucket',
  environment: 'prod',
  owner: 'platform-team',
  approved_by: 'jana.srimanta@gmail.com',
  terraform_module: 'modules/evidence-bucket',
  expires_at: '2027-01-01T00:00:00Z',
});
console.log(row.status); // 'registered'

import { getOwnership } from '@projexlight/sdk-resource-registry';

const record = await getOwnership('aws:s3:projex-evidence-prod');
if (!record) throw new Error('unregistered resource');
console.log(record.owner, record.approved_by, record.status);

import { listResources } from '@projexlight/sdk-resource-registry';

const flagged = await listResources({
  status: 'quarantined',
  environment: 'prod',
  limit: 50,
});
for (const r of flagged) {
  console.log(r.resource_id, r.quarantine_reason);
}

import { reconcile } from '@projexlight/sdk-resource-registry';

const result = await reconcile({
  live_resource_ids: ['aws:s3:projex-evidence-prod', 'aws:rds:untracked-db'],
});
console.log(result.quarantined_expired); // ids past expires_at
console.log(result.orphans);             // live ids with no registry row
